import sys, os, json, csv, re, io


def norm_id(s):
    return str(s).strip().lower()


def norm_text(s):
    s = s.casefold()
    s = ''.join(ch if ch.isalnum() else ' ' for ch in s)
    return ' '.join(s.split())


def read_batch(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        text = f.read()
    lines = [l for l in text.split('\n')]
    lines = [l[:-1] if l.endswith('\r') else l for l in lines]
    meta = {}
    recs = []  # (ballot, contest, {rank: [marks]}) ; mark = ('c', id) / ('w', text)
    if path.endswith('.jsonl'):
        first = True
        for l in lines:
            if not l.strip():
                continue
            o = json.loads(l)
            if first:
                meta = o
                first = False
                continue
            rk = {}
            for m in o.get('marks', []):
                r = int(m['rank'])
                if 'write_in' in m and m['write_in'] is not None:
                    rk.setdefault(r, []).append(('w', m['write_in']))
                else:
                    rk.setdefault(r, []).append(('c', m['candidate']))
            recs.append((o.get('ballot'), o['contest'], rk))
    else:
        i = 0
        while i < len(lines):
            l = lines[i]
            if l.startswith('#'):
                m = re.match(r'#\s*([^:]*?)\s*:\s*(.*?)\s*$', l)
                if m:
                    meta[m.group(1).strip().lower()] = m.group(2)
                i += 1
            elif not l.strip():
                i += 1
            else:
                break
        body = [l for l in lines[i:] if l.strip()]
        rd = csv.reader(io.StringIO('\n'.join(body), newline=''))
        header = None
        for row in rd:
            if not row:
                continue
            if header is None:
                header = [h.strip() for h in row]
                continue
            d = dict(zip(header, row))
            rk = {}
            for k, v in d.items():
                mm = re.fullmatch(r'rank(\d+)', k)
                if not mm or v is None or v == '':
                    continue
                r = int(mm.group(1))
                for part in v.split('|'):
                    if part == '':
                        continue
                    if part.startswith('WI:'):
                        rk.setdefault(r, []).append(('w', part[3:]))
                    else:
                        rk.setdefault(r, []).append(('c', part))
            recs.append((d.get('ballot'), d.get('contest'), rk))
    return meta, recs


def prepare(rk, c, wmap, withdrawn, valid):
    """Return list of rankings states for ranks 1..max_ranks."""
    seen = set()
    out = []
    for r in range(1, c['max_ranks'] + 1):
        marks = rk.get(r, [])
        cands = set()
        for kind, v in marks:
            if kind == 'w':
                t = norm_text(v)
                if t in wmap:
                    cands.add(wmap[t])
            else:
                cands.add(norm_id(v))
        if not cands:
            out.append(('skip', None))
            continue
        cands = {x for x in cands if x not in withdrawn}
        if not cands:
            out.append(('pass', None))
            continue
        before = set(cands)
        cands = {x for x in cands if x not in seen}
        seen |= before
        if not cands:
            out.append(('skip', None))
        elif len(cands) == 1:
            out.append(('choice', next(iter(cands))))
        else:
            out.append(('over', None))
    return out


def read_ballot(states, cont):
    n = len(states)
    for i, (k, v) in enumerate(states):
        if k == 'choice':
            if v in cont:
                return v
        elif k == 'pass':
            continue
        elif k == 'over':
            return None
        elif k == 'skip':
            if i + 1 >= n or states[i + 1][0] == 'skip':
                return None
    return None


def count_contest(c, ballots):
    cands = []  # (orig id, norm)
    withdrawn = set()
    for x in c.get('candidates', []):
        if x.get('status') == 'withdrawn':
            withdrawn.add(norm_id(x['id']))
        else:
            cands.append(x['id'])
    wmap = {}
    for w in c.get('write_ins', []):
        cands.append(w['id'])
        for name in [w['name']] + list(w.get('aliases', [])):
            wmap.setdefault(norm_text(name), norm_id(w['id']))
    orig = {norm_id(i): i for i in cands}
    lot = [norm_id(x) for x in c.get('lot_order', [])]
    states = [prepare(rk, c, wmap, withdrawn, None) for rk in ballots]
    total = len(states)
    cont = set(orig)
    rounds = []
    hist = []
    winner = None
    while True:
        tal = {k: 0 for k in cont}
        ex = 0
        for st in states:
            r = read_ballot(st, cont)
            if r is None:
                ex += 1
            else:
                tal[r] += 1
        active = total - ex
        rd = {"round": len(rounds) + 1,
              "tallies": {orig[k]: v for k, v in tal.items()},
              "exhausted": ex, "eliminated": []}
        rounds.append(rd)
        hist.append(tal)
        if active == 0:
            break
        win = None
        if len(cont) == 1:
            win = next(iter(cont))
        else:
            for k, v in tal.items():
                if v * 2 > active:
                    win = k
        if win is not None:
            winner = orig[win]
            break
        zeros = [k for k, v in tal.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tal.values())
            tied = [k for k, v in tal.items() if v == m]
            j = len(hist) - 2
            while len(tied) > 1 and j >= 0:
                mm = min(hist[j][k] for k in tied)
                tied = [k for k in tied if hist[j][k] == mm]
                j -= 1
            if len(tied) > 1:
                tied.sort(key=lambda k: lot.index(k) if k in lot else -1)
                tied = [tied[-1]]
            elim = tied
        rd["eliminated"] = sorted(orig[k] for k in elim)
        cont -= set(elim)
    return {"contest": c['id'], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    cvr = os.path.join(indir, 'cvr')
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        meta, recs = read_batch(p)
        b = str(meta.get('batch'))
        rev = int(str(meta.get('revision')).strip())
        if b not in best or rev > best[b][0]:
            best[b] = (rev, str(meta.get('status', 'final')).strip().lower(), recs)
    per = {}
    for rev, status, recs in best.values():
        if status == 'void':
            continue
        for ballot, contest, rk in recs:
            per.setdefault(contest, []).append(rk)
    res = {"election": el.get('election'),
           "contests": [count_contest(c, per.get(c['id'], [])) for c in el['contests']]}
    with open(outfile, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
